#include <stdio.h>
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int a[1000], max;
    for (int i = 0; i < n; i++) if (scanf("%d", &a[i]) != 1) return 1;
    max = a[0];
    for (int i = 1; i < n; i++) if (a[i] > max) max = a[i];
    printf("%d\n", max);
    return 0;
}
